contracts/ERC4337Paymaster.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";

/**
 * @title ERC4337Paymaster
 * @dev ERC-4337 compatible paymaster for gasless transactions
 * @notice This paymaster can sponsor gas fees for UserOperations
 */
contract ERC4337Paymaster is Ownable, ReentrancyGuard {
    using SafeERC20 for IERC20;

    IEntryPoint public immutable entryPoint;

    mapping(address => bool) public authorizedUsers;
    mapping(address => uint256) public userGasSpent;
    mapping(address => uint256) public userDeposits;

    uint256 public constant UNSTAKE_DELAY = 0;
    uint256 public constant PAYMASTER_STAKE = 1 ether;

    event UserOperationSponsored(
        address indexed user,
        address indexed target,
        uint256 gasUsed,
        uint256 gasPrice
    );

    event UserAuthorized(address indexed user);
    event UserDeauthorized(address indexed user);
    event Deposited(address indexed user, uint256 amount);
    event Withdrawn(address indexed user, uint256 amount);

    modifier onlyEntryPoint() {
        require(msg.sender == address(entryPoint), "Only entry point can call this function");
        _;
    }

    modifier onlyAuthorized() {
        require(authorizedUsers[msg.sender] || msg.sender == owner(), "Not authorized");
        _;
    }

    constructor(IEntryPoint _entryPoint) Ownable(msg.sender) {
        entryPoint = _entryPoint;
    }

    /**
     * @dev Validate paymaster user operation
     * @param userOp The user operation to validate
     * @param userOpHash The hash of the user operation
     * @param maxCost The maximum cost for this operation
     */
    function validatePaymasterUserOp(
        IEntryPoint.UserOperation calldata userOp,
        bytes32 userOpHash,
        uint256 maxCost
    ) external onlyEntryPoint returns (bytes memory context, uint256 validationData) {
        require(authorizedUsers[userOp.sender] || userOp.sender == owner(), "Not authorized");
        require(maxCost <= address(this).balance, "Insufficient balance");

        // Return context and validation data
        context = abi.encode(userOp.sender, maxCost);
        validationData = 0;
    }

    /**
     * @dev Post-operation callback
     * @param mode The post-operation mode
     * @param context The context from validatePaymasterUserOp
     * @param actualGasCost The actual gas cost
     */
    function postOp(
        IEntryPoint.PostOpMode mode,
        bytes calldata context,
        uint256 actualGasCost
    ) external onlyEntryPoint {
        (address user, uint256 maxCost) = abi.decode(context, (address, uint256));

        if (mode == IEntryPoint.PostOpMode.opSucceeded) {
            // Operation succeeded, update user's gas spent
            userGasSpent[user] += actualGasCost;

            emit UserOperationSponsored(user, address(0), actualGasCost, tx.gasprice);
        } else {
            // Operation failed, refund the user if they paid
            if (userDeposits[user] > 0) {
                uint256 refund = userDeposits[user];
                userDeposits[user] = 0;
                (bool success, ) = payable(user).call{value: refund}("");
                require(success, "Refund failed");
            }
        }
    }

    /**
     * @dev Deposit funds to the paymaster
     */
    function deposit() external payable {
        require(msg.value > 0, "Must send some ETH");
        userDeposits[msg.sender] += msg.value;
        emit Deposited(msg.sender, msg.value);
    }

    /**
     * @dev Withdraw funds from the paymaster
     * @param amount The amount to withdraw
     */
    function withdraw(uint256 amount) external nonReentrant {
        require(userDeposits[msg.sender] >= amount, "Insufficient balance");
        userDeposits[msg.sender] -= amount;

        (bool success, ) = payable(msg.sender).call{value: amount}("");
        require(success, "Withdrawal failed");

        emit Withdrawn(msg.sender, amount);
    }

    /**
     * @dev Authorize a user to use the paymaster
     * @param user The address to authorize
     */
    function authorizeUser(address user) external onlyOwner {
        require(user != address(0), "Invalid user address");
        authorizedUsers[user] = true;
        emit UserAuthorized(user);
    }

    /**
     * @dev Deauthorize a user from using the paymaster
     * @param user The address to deauthorize
     */
    function deauthorizeUser(address user) external onlyOwner {
        require(user != address(0), "Invalid user address");
        authorizedUsers[user] = false;
        emit UserDeauthorized(user);
    }

    /**
     * @dev Get the balance of the paymaster
     * @return The current balance
     */
    function getBalance() external view returns (uint256) {
        return address(this).balance;
    }

    /**
     * @dev Get the total gas spent by a user
     * @param user The user address
     * @return The total gas spent
     */
    function getUserGasSpent(address user) external view returns (uint256) {
        return userGasSpent[user];
    }

    /**
     * @dev Get the deposit balance of a user
     * @param user The user address
     * @return The deposit balance
     */
    function getUserDeposit(address user) external view returns (uint256) {
        return userDeposits[user];
    }

    /**
     * @dev Check if a user is authorized
     * @param user The user address
     * @return True if authorized, false otherwise
     */
    function isAuthorized(address user) external view returns (bool) {
        return authorizedUsers[user];
    }

    /**
     * @dev Emergency function to recover stuck tokens (owner only)
     * @param token The token address
     * @param to The recipient address
     * @param amount The amount to recover
     */
    function emergencyRecover(
        address token,
        address to,
        uint256 amount
    ) external onlyOwner {
        require(to != address(0), "Invalid recipient");
        require(amount > 0, "Invalid amount");

        if (token == address(0)) {
            // Recover ETH
            (bool success, ) = to.call{value: amount}("");
            require(success, "ETH recovery failed");
        } else {
            // Recover ERC20 tokens
            IERC20(token).safeTransfer(to, amount);
        }
    }

    /**
     * @dev Add stake to the entry point (required for paymaster)
     */
    function addStake() external payable onlyOwner {
        entryPoint.addStake{value: msg.value}(UNSTAKE_DELAY);
    }

    /**
     * @dev Unlock stake from the entry point
     */
    function unlockStake() external onlyOwner {
        entryPoint.unlockStake();
    }

    /**
     * @dev Withdraw stake from the entry point
     * @param withdrawAddress The address to withdraw to
     */
    function withdrawStake(address payable withdrawAddress) external onlyOwner {
        entryPoint.withdrawStake(withdrawAddress);
    }

    /**
     * @dev Deposit to the entry point
     * @param account The account to deposit to
     */
    function depositTo(address account) external payable {
        entryPoint.depositTo{value: msg.value}(account);
    }

    /**
     * @dev Withdraw from the entry point
     * @param withdrawAddress The address to withdraw to
     * @param amount The amount to withdraw
     */
    function withdrawTo(address payable withdrawAddress, uint256 amount) external onlyOwner {
        entryPoint.withdrawTo(withdrawAddress, amount);
    }

    // Fallback function to receive ETH
    receive() external payable {
        emit Deposited(msg.sender, msg.value);
    }
}

/**
 * @title IEntryPoint
 * @dev Interface for the EntryPoint contract
 */
interface IEntryPoint {
    struct UserOperation {
        address sender;
        uint256 nonce;
        bytes initCode;
        bytes callData;
        uint256 callGasLimit;
        uint256 verificationGasLimit;
        uint256 preVerificationGas;
        uint256 maxFeePerGas;
        uint256 maxPriorityFeePerGas;
        bytes paymasterAndData;
        bytes signature;
    }

    enum PostOpMode {
        opSucceeded,
        opReverted,
        postOpReverted
    }

    function handleOps(UserOperation[] calldata ops, address payable beneficiary) external;
    function simulateValidation(UserOperation calldata userOp) external;
    function depositTo(address account) external payable;
    function withdrawTo(address payable withdrawAddress, uint256 amount) external;
    function addStake(uint256 unstakeDelay) external payable;
    function unlockStake() external;
    function withdrawStake(address payable withdrawAddress) external;
}

