// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "./SimpleERC4337Account.sol";

/**
 * @title SimpleAccountFactory
 * @dev Minimal factory that deploys SimpleERC4337Account instances and initializes them with an owner
 */
contract SimpleAccountFactory {
    IEntryPoint public immutable entryPoint;

    event AccountDeployed(address indexed account, address indexed owner);

    constructor(IEntryPoint _entryPoint) {
        entryPoint = _entryPoint;
    }

    /**
     * @dev Deploy a new SimpleERC4337Account and initialize it with the provided owner
     * @param owner The owner of the new smart account
     * @return account The deployed smart account address
     */
    function createAccount(address owner) external returns (address account) {
        SimpleERC4337Account acc = new SimpleERC4337Account(entryPoint);
        acc.initialize(owner);
        account = address(acc);
        emit AccountDeployed(account, owner);
    }
}

